import numpy as np
from scipy.optimize import minimize
import time

# --- Constants ---
N = 26
R_MIN = 1e-6
SAFETY = 1e-9

# --- Helper Functions ---
def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]

# --- SLSQP Definitions ---
def objective(z): return -np.sum(z[N*2:])
def ineq_boundary(z):
    c, r = z_to_cr(z)
    return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
def ineq_nonoverlap(z):
    c, r = z_to_cr(z)
    diff = c[:, None, :] - c[None, :, :]
    dist = np.sqrt(np.sum(diff**2, axis=-1) + 1e-12)
    iu = np.triu_indices(N, 1)
    return dist[iu] - (r[iu[0]] + r[iu[1]])

# --- Post-processing Projection ---
def ensure_validity(centers, radii):
    radii = np.maximum(radii, 0)
    for i in range(N):
        radii[i] = min(radii[i], centers[i,0], 1 - centers[i,0], centers[i,1], 1 - centers[i,1])
    for _ in range(5):
        violations = 0
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(centers[i] - centers[j])
                rad_sum = radii[i] + radii[j]
                if dist < rad_sum:
                    violations+=1; scale = (dist/rad_sum)*(1.0-SAFETY); radii[i]*=scale; radii[j]*=scale
        if violations == 0: break
    return centers, radii

# --- Data Loading ---
def load_true_sota_data():
    centers_path = 'storage/Prometheus/true_sota_baseline/centers.txt'
    radii_path = 'storage/Prometheus/true_sota_baseline/radii.txt'
    try:
        return np.loadtxt(centers_path), np.loadtxt(radii_path)
    except Exception: return None, None

def construct_packing() -> tuple:
    base_centers, base_radii = load_true_sota_data()
    if base_centers is None:
        return np.zeros((N, 2)), np.zeros(N)

    # Initialize with the true SOTA score
    best_score = np.sum(base_radii)
    best_packing = (base_centers, base_radii)
    print(f"Initial SOTA baseline score: {best_score}")

    # --- Final Exhaustive Jitter Spectrum Search ---
    jitter_amplitudes = [1e-5, 5e-5, 1e-4, 5e-4, 1e-3, 2.5e-3, 5e-3]
    restarts_per_amplitude = 10

    bounds = [(0,1)]*N*2 + [(R_MIN, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    for amp in jitter_amplitudes:
        print(f"--- Testing Jitter Amplitude: {amp:.1e} ---")
        for i in range(restarts_per_amplitude):
            np.random.seed((int(time.time()*1000) + i*1000 + int(amp*1e6)) % (2**32))

            jitter = np.random.uniform(-amp, amp, size=base_centers.shape)
            perturbed_centers = np.clip(base_centers + jitter, 1e-6, 1 - 1e-6)
            initial_z = cr_to_z(perturbed_centers, base_radii)

            res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 1000, 'ftol': 1e-10})

            if res.success:
                c, r = z_to_cr(res.x)
                temp_c, temp_r = ensure_validity(c, r)
                current_score = np.sum(temp_r)
                if current_score > best_score:
                    print(f"  Run {i+1}: NEW SOTA FOUND! Score: {current_score:.18f}")
                    best_score = current_score
                    best_packing = (temp_c, temp_r)

    return best_packing[0], best_packing[1]
